import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync,existsSync} from 'node:fs';
import {resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/',read=(path:string)=>JSON.parse(readFileSync(path,'utf8'));
const path=root+'evidence/B11.74.3-records.json',record=read(path),catalog=discoverInventory(process.cwd());
assert.equal(catalog.files.length,450);assert.equal(catalog.packages.length,2);assert.deepEqual(catalog,read(root+'executable-catalog.json'));assert.deepEqual(validateInventory(catalog,read(root+'quality-classifications.json')),[]);
for(const input of record.sourceInputs){assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')));for(const rows of [record.diagnosticCoverage.sourceInputs,record.decisionChecks.sourceInputs,record.native.sourceInputs])assert.equal(rows.find((row:any)=>row.path===input.path).sourceHash,input.sourceHash);}
const coverage=createCoverageMap(record.diagnosticCoverage.measurement.rawCoverage);
for(const entry of record.diagnosticCoverage.measurement.files){assert.deepEqual(coverage.fileCoverageFor(resolve(entry.path)).toSummary().data,entry.metrics);for(const name of ['statements','branches','functions','lines'])assert.equal(entry.metrics[name].pct,100);}
assert.equal(record.diagnosticCoverage.measurement.files.find((file:any)=>file.path.startsWith('tests/')).metrics.branches.total,0);
for(const run of [record.checks[0],...record.native.runs]){assert.equal(run.exit,0);assert(run.output.includes('24 pass')&&run.output.includes('0 fail')&&run.output.includes('888 expect()'));}
assert.equal(record.decisionChecks.runs.length,14);assert.equal(record.decisionChecks.runs[0].exit,0);for(const run of record.decisionChecks.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
assert(!existsSync(record.removedRuntimeRoot));assert.equal(record.retainedOwnerFinding.sourceHash,sourceHash(readFileSync(record.retainedOwnerFinding.path,'utf8')));
const ledger=read(root+'work-items.json'),items=new Map<string,any>(ledger.items.map((item:any)=>[item.id,item])),done=new Set<string>();
function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id),'Invalid dependency '+id);if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}
assert.equal(items.size,232);assert.equal(items.size,ledger.items.length);for(const id of items.keys())visit(id);
assert.equal(ledger.current_item,'B11.74.3');assert.deepEqual(ledger.items.filter((item:any)=>item.status==='active').map((item:any)=>item.id),['B11.74.3']);
const inventory=items.get('B11.74.3').progress.repositoryInventory;
assert.equal(inventory.length,17);assert.equal(inventory.filter((row:any)=>row.status.startsWith('local')).length,3);
assert.equal(inventory.filter((row:any)=>row.status.startsWith('local')).reduce((sum:number,row:any)=>sum+row.nativePrepareSites,0),12);
for(const entry of inventory)assert.equal(entry.sourceHash,sourceHash(readFileSync(entry.path,'utf8')));
assert.equal(items.get('B11.74').status,'pending');assert.equal(items.get('B11.74.6').status,'pending');assert(!readFileSync('src/infrastructure/database/connection.ts','utf8').includes('OwnedDatabase'));
record.validation={command:'bun .git/b11-records-validate.ts',exit:0,recordedAt:new Date().toISOString(),result:'450-file/two-package catalog and 232-item acyclic ledger reconcile; three of seventeen repositories migrated; twelve disposal sites and thirteen failing faults verified; current Windows source/metric/native bindings match; runtime removed; factory activation and final acceptance remain pending.',source:readFileSync('.git/b11-records-validate.ts','utf8')};
writeFileSync(path,JSON.stringify(record,null,2)+'\n');console.log(record.validation.result);
